import{_ as o,o as a,c as t,ah as n}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Getting started","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/premiers-pas.md","filePath":"src/en/guide/premiers-pas.md"}'),r={name:"en/guide/premiers-pas.md"};function i(s,e,u,c,d,l){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>What applies to every account, whatever your roles.</p><h2 id="create-your-account" tabindex="-1">Create your account <a class="header-anchor" href="#create-your-account" aria-label="Permalink to &quot;Create your account&quot;">​</a></h2><p>There is no sign-up form for Kura: the account is born from your first step on the NextBoxx website, for example submitting a candidature or registering for an event. If your e-mail address already has an account, it is reused.</p><p>For a new account, the acknowledgement e-mail contains a link to <strong>choose your password</strong>. The link is valid for 7 days and works only once. If it has expired, use &quot;Forgot your password?&quot; on the login page.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>Go to the <strong>Log in</strong> page and enter your e-mail and password. &quot;Remember me&quot; keeps the session open on this device.</p><p>If you have added a <strong>passkey</strong>, you may prefer it: &quot;Sign in with a passkey&quot; saves you typing a password. If you have enabled two-factor authentication, Kura then asks for the code from your app, or one of your recovery codes.</p><p>An account inactive for a year is deactivated, its data kept. It is reactivated as soon as you sign in again or submit a new candidature.</p><h2 id="secure-your-account" tabindex="-1">Secure your account <a class="header-anchor" href="#secure-your-account" aria-label="Permalink to &quot;Secure your account&quot;">​</a></h2><p>In <strong>Settings → Security</strong>:</p><ul><li>change your password;</li><li>enable <strong>two-factor authentication</strong> with an authenticator app. Keep the recovery codes shown on activation: they are useful if you lose your phone;</li><li>add one or more <strong>passkeys</strong> (for example the one on your computer or phone), and name them so you can recognise them.</li></ul><h2 id="your-profile" tabindex="-1">Your profile <a class="header-anchor" href="#your-profile" aria-label="Permalink to &quot;Your profile&quot;">​</a></h2><p>In <strong>Settings → Profile</strong>: your name, e-mail address, phone and photo. Enter your phone in international format (for example <code>+228 90 00 00 00</code>): this is the number to which Kura can send payment and admission reminders on WhatsApp. If you change your e-mail address, a verification link is sent to you.</p><p><strong>Settings → Language</strong> chooses French or English, <strong>Settings → Appearance</strong> the light theme, the dark theme or your system&#39;s.</p><h2 id="ask-for-a-role" tabindex="-1">Ask for a role <a class="header-anchor" href="#ask-for-a-role" aria-label="Permalink to &quot;Ask for a role&quot;">​</a></h2><p><strong>Settings → Roles</strong> shows your active roles and the history of your requests.</p><p>To ask for another one, choose it in &quot;Ask for a role&quot;, add a few words of introduction if you wish and send. The request is examined by the person responsible for that role; you are told by e-mail of the decision, with a reason in case of refusal. While you wait, your other roles stay active, and a refusal does not change them.</p><p>Staff roles (Coordinator, Advisor, Direction, etc.) cannot be requested: the Administrator assigns them. The Candidate, Participant and Learner roles arrive automatically with the corresponding step.</p><h3 id="individual-or-organization-account" tabindex="-1">Individual or organization account <a class="header-anchor" href="#individual-or-organization-account" aria-label="Permalink to &quot;Individual or organization account&quot;">​</a></h3><p>An account is either an <strong>individual</strong> or an <strong>organization</strong>. A company wishing to fund learners, order a training on quote or look for profiles needs an organization account. It is not created separately: you <strong>convert</strong> your individual account.</p><p>In <strong>Settings → Roles</strong>, under &quot;Organization account&quot;, enter the company name, attach a supporting document (company registration or equivalent, PDF, JPG or PNG, 5 MB at most) and send. The Administrator examines the request. On approval, the account takes the company name as its name, and its history stays readable, read-only.</p><p>An organization account can no longer apply or register for an event personally.</p><h2 id="my-documents" tabindex="-1">My documents <a class="header-anchor" href="#my-documents" aria-label="Permalink to &quot;My documents&quot;">​</a></h2><p><strong>My documents</strong> (Journeys section) gathers everything Kura has produced for your account, each with its reference and date:</p><ul><li>training agreements, tripartite funding agreements and internship agreements;</li><li>the welcome booklet;</li><li>invoices and credit notes;</li><li>certificate, partial attestation and transcript;</li><li>decision letters of your candidatures.</li></ul><p>A filter by document type helps find the right one. Each document opens or downloads as a PDF.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Kura writes to you to keep you informed: the e-mail is always sent. If your Sève account is open, the message also arrives in Sève; if you have entered a phone, some reminders (payments, admission) are also sent on WhatsApp. A channel that fails does not stop the others.</p>',29)])])}const g=o(r,[["render",i]]);export{p as __pageData,g as default};
